// Arbeitsliste als HTML-Seite: App mit Seitenleiste, kompakten Zeilen, Suche und Filter. Werte werden escaped, weil Mailtexte von außen kommen.
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const reviews = $('Offene Reviews laden').all().map((i) => i.json).filter((r) => r.id);
const tickets = $('Tickets laden').all().map((i) => i.json).filter((r) => r.id);
const erledigtHinweis = String($('Webhook Arbeitsliste').first().json.query?.erledigt ?? '') === '1';

const PFAD = {
  mail: '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>',
  check: '<path d="m5 12.5 4.5 4.5L19 7.5"/>',
  alarm: '<path d="M12 4 3 19h18L12 4Z"/><path d="M12 10v4M12 17v.5"/>',
  inbox: '<path d="M4 13V6a2 2 0 0 1 2-2h12a2 2 0 0 1 2 2v7"/><path d="M4 13h4l1 2h6l1-2h4v5a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-5Z"/>',
  robot: '<rect x="4" y="8" width="16" height="11" rx="3"/><path d="M12 4v4M9 13v1M15 13v1"/>',
  suche: '<circle cx="11" cy="11" r="6"/><path d="m20 20-4.2-4.2"/>',
  pfeil: '<path d="m9 6 6 6-6 6"/>',
  senden: '<path d="M4 12 20 4l-4 16-4-6-8-2Z"/>',
  neu: '<path d="M20 12a8 8 0 1 1-2.3-5.7M20 4v5h-5"/>',
  schild: '<path d="M12 3 5 6v6c0 4.2 2.8 7.2 7 9 4.2-1.8 7-4.8 7-9V6l-7-3Z"/><path d="m9 12 2 2 4-4"/>',
  team: '<circle cx="9" cy="8" r="3"/><path d="M3.5 19c.6-3 2.8-4.5 5.5-4.5s4.9 1.5 5.5 4.5M16 6.5a3 3 0 0 1 0 5M17.5 14.7c1.8.5 3 1.9 3.5 4.3"/>',
  stern: '<path d="m12 4 2.4 5 5.4.7-4 3.8 1 5.4-4.8-2.7-4.8 2.7 1-5.4-4-3.8 5.4-.7L12 4Z"/>',
};
const icon = (name, klasse = 'ico') => `<svg class="${klasse}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${PFAD[name]}</svg>`;

const KATEGORIE = {
  angebot: 'Angebot', auftragsbestaetigung: 'Auftragsbestätigung', reklamation: 'Reklamation', lieferverzug: 'Lieferverzug',
  rechnung: 'Rechnung', lieferavis: 'Lieferavis', preisaenderung: 'Preisänderung', stammdatenaenderung: 'Stammdaten',
  compliance: 'Compliance', werbung: 'Werbung', sonstiges: 'Sonstiges',
};

const beschreibe = (ab) => {
  const zahl = (n) => Number(n).toLocaleString('de-DE', { maximumFractionDigits: 4 });
  const datum = (d) => (d ? (typeof d === 'string' ? d : new Date(d).toISOString()).slice(0, 10).split('-').reverse().join('.') : '–');
  const texte = (ab.abweichungen ?? []).map((a) => ({
    preis: `Preis ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)} ${a.waehrung ?? ''}`,
    waehrung: `Währung ${a.bestellt} → ${a.bestaetigt}: Preis in anderer Währung bestätigt`,
    menge: `Menge ${zahl(a.bestellt)} → ${zahl(a.bestaetigt)}${a.grund ? ` (${a.grund})` : ''}`,
    stammdaten_pruefen: `Stammdaten prüfen${a.hinweis ? `: ${a.hinweis}` : ''}`,
    termin_unsicher: `Termin unsicher, gewünscht ${datum(a.gewuenscht)}`,
    termin_fehlt: `Kein Termin bestätigt, gewünscht ${datum(a.gewuenscht)}`,
    termin_spaeter: `Termin ${datum(a.gewuenscht)} → ${datum(a.bestaetigt)}`,
  }[a.art] ?? a.art));
  for (const g of ab.pruefgruende ?? []) {
    texte.push({
      neuer_lieferant: 'Neuer Lieferant: Kontakt aufnehmen und Termin absichern',
      liefertreue_unter_schwelle: `Liefertreue ${ab.liefertreue} % unter ${ab.schwelle} % (${ab.abc_xyz}-Artikel)`,
      blindbestaetigung_verdacht: `AB nach ${ab.bearbeitungszeit_minuten} Minuten: Blindbestätigung?`,
      absender_domain_abweichend: 'Absender-Domain passt nicht zum Lieferanten',
    }[g] ?? g);
  }
  return texte;
};

const FELD = { einzelpreis: 'Einzelpreis', menge: 'Menge', betrag: 'Betrag', liefertermin: 'Liefertermin', bestellnummer: 'Bestellnummer', rechnungsnummer: 'Rechnungsnummer', angebotsnummer: 'Angebotsnummer' };
const warnung = (w) => {
  const [art, wert] = String(w).split(':');
  if (art === 'beleg_fehlt') return `${FELD[wert] ?? wert} nicht im Mailtext belegt`;
  return String(w);
};
const GRUND = {
  konfidenz_niedrig: 'Modell war unsicher', bankdatenaenderung: 'Bankdaten geändert: Betrugsverdacht', stammdatenaenderung_pruefen: 'Stammdatenänderung: immer prüfen',
  prompt_injection_verdacht: 'Verdacht auf Manipulation des Modells', bestellung_unbekannt: 'Bestellnummer nicht im System', kategorie_unplausibel: 'Kategorie unplausibel',
  llm_fehler: 'Modell nicht erreichbar', json_ungueltig: 'Antwort des Modells ungültig', schema_verletzt: 'Antwort des Modells ungültig',
};
const grund = (g) => (String(g).startsWith('pflichtfeld_fehlt:') ? `Pflichtangabe fehlt: ${String(g).split(':')[1].replace('|', ' oder ')}` : GRUND[g] ?? String(g));

const adresse = (absender) => String(absender ?? '').match(/<([^>]+)>/)?.[1] ?? String(absender ?? '').trim();
const anbieter = (t) => t.lieferant || String(t.absender ?? '').replace(/<[^>]*>/g, '').trim() || 'Unbekannter Absender';
const mailto = (an, betreff, text) => `mailto:${esc(encodeURIComponent(an ?? '').replace(/%40/g, '@'))}?subject=${esc(encodeURIComponent(betreff ?? ''))}&amp;body=${esc(encodeURIComponent(text ?? ''))}`;
const chip = (text, art = '') => `<span class="chip ${art}">${esc(text)}</span>`;

const rfq = (t) => {
  const gegenstand = t.artikel || (t.kategorie === 'angebot' ? t.betreff : '[Artikel eintragen]');
  const einleitung = t.kategorie === 'preisaenderung'
    ? `vielen Dank für Ihre Information zur Preisänderung. Bevor wir entscheiden, möchten wir ein aktuelles, vollständiges Angebot einholen für: ${gegenstand}.`
    : `vielen Dank für Ihr Angebot. Damit wir es mit anderen vergleichen können, bitten wir um ein vollständiges Angebot zu: ${gegenstand}.`;
  return {
    betreff: `Anfrage (RFQ): ${gegenstand}`,
    text: [
      'Guten Tag,', '', einleitung, '',
      'Bitte beantworten Sie jeden Punkt einzeln und mit Einheit, damit wir Angebote vergleichen können:',
      '1. Stückpreis in EUR, netto, je 1 Stück',
      '2. Mindestbestellmenge in Stück',
      '3. Lieferzeit in Tagen nach Auftragseingang',
      '4. Zahlungsziel in Tagen',
      '5. Skonto in Prozent (0, wenn keines)',
      '6. Preisgleitklausel: ja oder nein (Preis an einen Index gekoppelt?)',
      '7. Zertifizierung ISO 9001: gültig ja oder nein, mit Gültigkeitsdatum',
      '8. Zertifizierung ISO 14001: gültig ja oder nein, mit Gültigkeitsdatum',
      '9. CO2-Fußabdruck je Stück in kg CO2e',
      '10. Reklamationsquote in Prozent (letzte 12 Monate)',
      '11. Liefertreue in Prozent (letzte 12 Monate)',
      '',
      'Bitte senden Sie das Angebot als PDF mit Angebotsnummer und Gültigkeitsdatum sowie die ausgefüllte Lieferantenselbstauskunft.',
      'Angebotsfrist: [Datum eintragen]', '',
      'Mit freundlichen Grüßen', '[Name]', 'Hagemann Antriebstechnik GmbH, Einkauf',
    ].join('\n'),
  };
};

const zeile = (t) => {
  const ab = t.ab_pruefung ?? {};
  const hinweise = [
    ...(t.kategorie === 'auftragsbestaetigung' ? beschreibe(ab).map((x) => chip(x, 'warn')) : []),
    ...(t.warnungen ?? []).filter((w) => !String(w).startsWith('kategorie_korrigiert')).map((w) => chip(warnung(w), 'info')),
  ].join('');
  const entwurf = t.entwurf_text
    ? `<details class="panel"><summary>${icon('mail')}Antwortentwurf (${esc(t.foermlichkeit)}, ${esc(t.nachdruck)})</summary>
        ${(t.entwurf_warnungen ?? []).length ? `<p class="hinweis">Bitte prüfen: ${t.entwurf_warnungen.map(esc).join(', ')}</p>` : ''}
        <pre><b>${esc(t.entwurf_betreff)}</b>\n\n${esc(t.entwurf_text)}</pre>
        <a class="knopf" href="${mailto(t.entwurf_empfaenger, t.entwurf_betreff, t.entwurf_text)}">${icon('senden')}In Mailprogramm öffnen</a></details>`
    : '';
  const anfrage = ['angebot', 'preisaenderung'].includes(t.kategorie) ? rfq(t) : null;
  const anfrageBlock = anfrage
    ? `<details class="panel"><summary>${icon('mail')}Angebot anfordern (RFQ-Entwurf)</summary>
        <pre><b>${esc(anfrage.betreff)}</b>\n\n${esc(anfrage.text)}</pre>
        <a class="knopf" href="${mailto(adresse(t.absender), anfrage.betreff, anfrage.text)}">${icon('senden')}In Mailprogramm öffnen</a></details>`
    : '';
  const meta = [t.bestellnummer ? `Bestellung ${t.bestellnummer}` : '', t.artikel, t.angebotsnummer ? `Angebot ${t.angebotsnummer}` : '',
    t.rechnungsnummer ? `Rechnung ${t.rechnungsnummer}` : '', t.betrag ? `${Number(t.betrag).toLocaleString('de-DE', { minimumFractionDigits: 2 })} ${t.waehrung ?? ''}` : '',
    t.zustaendig ? `zuständig: ${t.zustaendig}` : ''].filter(Boolean).map(esc).join(' · ');
  const noch = t.kategorie === 'auftragsbestaetigung' && !t.entwurf_text && beschreibe(ab).length
    ? `<a class="knopf" href="/form/entwurf">${icon('mail')}Antwortentwurf erstellen</a>` : '';
  const erledigt = (klasse) => `<form method="post" action="/webhook/aufgabe" class="erledigt"><input type="hidden" name="id" value="${esc(t.id)}"><input type="hidden" name="token" value="${esc(t.token)}"><input type="hidden" name="rueck" value=""><button class="${klasse}" type="submit">${icon('check')}Erledigt</button></form>`;
  const sucht = `${anbieter(t)} ${t.betreff} ${t.zusammenfassung ?? ''} ${t.bestellnummer ?? ''} ${t.artikel ?? ''}`.toLowerCase();
  return `<details class="zeile dringlich-${esc(t.dringlichkeit ?? 'niedrig')}" data-team="${esc(t.team)}" data-text="${esc(sucht)}">
    <summary>
      <span class="punkt"></span>
      <span class="kat kat-${esc(t.kategorie)}">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span>
      <span class="titel"><b>${esc(anbieter(t))}</b><span class="betreff">${esc(t.betreff)}</span></span>
      <span class="zeit">${t.dringlichkeit === 'hoch' ? '<span class="dringend">Dringend</span>' : ''}${esc(t.erstellt)}</span>
      ${erledigt('schnell')}
      ${icon('pfeil', 'ico pfeil')}
      <span class="zweite">${t.zusammenfassung ? `<span class="zusammenfassung">${esc(t.zusammenfassung)}</span>` : ''}${hinweise ? `<span class="chips">${hinweise}</span>` : ''}</span>
    </summary>
    <div class="inhalt">
      <p class="meta">${meta}</p>
      ${entwurf}${anfrageBlock}
      ${noch ? `<div class="aktionen">${noch}</div>` : ''}
    </div>
  </details>`;
};

const offen = tickets.filter((t) => t.status === 'offen');
const automatisch = tickets.filter((t) => ['bestaetigt', 'abgelegt'].includes(t.status));
const REIHENFOLGE = ['Einkauf', 'Strategischer Einkauf', 'Disposition', 'Qualitätsmanagement', 'Kreditorenbuchhaltung', 'Einkauf Sammelpostfach'];
const rang = (team) => (REIHENFOLGE.indexOf(team) === -1 ? 99 : REIHENFOLGE.indexOf(team));
const teams = [...new Set(offen.map((t) => t.team))].sort((a, b) => rang(a) - rang(b));

const teamBloecke = teams.map((team) => {
  const liste = offen.filter((t) => t.team === team);
  return `<section class="gruppe" data-gruppe="${esc(team)}"><h2>${esc(team)}<span class="zahl">${liste.length}</span></h2><div class="liste">${liste.map(zeile).join('')}</div></section>`;
}).join('');

const reviewZeilen = reviews.map((r) => `
  <details class="zeile pruefung" data-team="Prüfung" data-text="${esc(`${r.betreff} ${r.absender}`.toLowerCase())}" open>
    <summary>
      <span class="punkt"></span>
      <span class="kat kat-pruefung">Prüfung nötig</span>
      <span class="titel"><b>${esc(r.betreff)}</b><span class="betreff">${esc(r.absender)}</span></span>
      <span class="zeit">${esc(r.erstellt)}</span>
      ${icon('pfeil', 'ico pfeil')}
      <span class="zweite"><span class="chips">${r.gruende.map((g) => chip(grund(g), 'warn')).join('')}</span></span>
    </summary>
    <div class="inhalt">
      <p class="zusammenfassung">Vorschlag des Modells: <b>${esc(KATEGORIE[r.vorschlag] ?? r.vorschlag ?? '–')}</b> (Konfidenz ${esc(r.konfidenz ?? '–')}). ${esc(r.begruendung ?? '')}</p>
      <details class="panel"><summary>${icon('mail')}Mailtext anzeigen</summary><pre>${esc(r.text)}</pre></details>
      <div class="aktionen"><a class="knopf haupt" href="/form/review">${icon('check')}Review abschließen (ID ${esc(r.id)})</a></div>
    </div>
  </details>`).join('');

const automatischZeilen = automatisch.slice(0, 30).map((t) =>
  `<li><span class="kat kat-${esc(t.kategorie)} klein">${esc(KATEGORIE[t.kategorie] ?? t.kategorie)}</span><span class="text"><b>${esc(anbieter(t))}</b> ${esc(t.betreff)}</span><span class="zeit">${esc(t.status === 'abgelegt' ? 'abgelegt' : 'bestätigt')} · ${esc(t.erstellt)}</span></li>`).join('');

const nav = (filter, text, zahl, symbol) => `<button class="nav" type="button" data-filter="${esc(filter)}">${icon(symbol)}<span class="nav-text">${esc(text)}</span><span class="nav-zahl">${zahl}</span></button>`;
const navigation = [nav('', 'Alle Aufgaben', offen.length + reviews.length, 'inbox')]
  .concat(reviews.length ? [nav('Prüfung', 'Zur Prüfung', reviews.length, 'alarm')] : [])
  .concat(teams.map((team) => nav(team, team, offen.filter((t) => t.team === team).length, 'team'))).join('');

const heute = new Date().toLocaleDateString('de-DE', { weekday: 'long', day: 'numeric', month: 'long' });
const uhr = new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });
const leer = !offen.length && !reviews.length;

const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mail-Triage</title>
<style>
  :root {
    --leinwand: #f5f5f2; --flaeche: #ffffff; --linie: #e8e6e1; --linie-stark: #d6d3cc;
    --tinte: #15181d; --tinte-2: #3f444d; --tinte-3: #6c727c;
    --akzent: #2457f5; --akzent-dunkel: #1b45cc; --akzent-hell: #eaf0ff;
    --seite: #11151b; --seite-text: #aab1bd; --seite-hell: #ffffff; --seite-aktiv: rgba(255, 255, 255, .09);
    --ok: #0b7a4b; --ok-hell: #e7f6ee; --warn: #a15c07; --warn-hell: #fff4e0; --rot: #c8301f; --rot-hell: #fdeceb;
    --schrift: 'Inter', 'Segoe UI Variable Text', 'Segoe UI Variable', 'Segoe UI', system-ui, -apple-system, Roboto, 'Helvetica Neue', Arial, sans-serif;
    --schatten-1: 0 1px 2px rgba(17, 21, 27, .05); --schatten-2: 0 1px 3px rgba(17, 21, 27, .06), 0 8px 24px -8px rgba(17, 21, 27, .12);
  }
  * { box-sizing: border-box; }
  html, body { height: 100%; }
  body { margin: 0; background: var(--leinwand); color: var(--tinte); font: 400 14px/1.5 var(--schrift); letter-spacing: -.006em; -webkit-font-smoothing: antialiased; font-feature-settings: 'cv11', 'ss01'; }
  .ico { width: 16px; height: 16px; flex: none; }
  .app { display: grid; grid-template-columns: 252px 1fr; min-height: 100%; }
  .seite { background: var(--seite); color: var(--seite-text); padding: 18px 12px; display: flex; flex-direction: column; gap: 6px; position: sticky; top: 0; height: 100vh; }
  .marke { display: flex; align-items: center; gap: 10px; padding: 4px 8px 16px; color: var(--seite-hell); }
  .marke .logo { width: 30px; height: 30px; border-radius: 9px; background: linear-gradient(140deg, #4d7bff, #1d3fd1); display: grid; place-items: center; color: #fff; box-shadow: inset 0 0 0 1px rgba(255,255,255,.18); }
  .marke b { font-size: 15px; font-weight: 650; letter-spacing: -.015em; } .marke small { display: block; color: var(--seite-text); font-size: 11.5px; margin-top: -2px; }
  .gruppentitel { font-size: 11px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: #6f7785; padding: 10px 10px 4px; }
  .nav { all: unset; box-sizing: border-box; display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 9px; cursor: pointer; color: var(--seite-text); font-size: 13.5px; width: 100%; transition: background .12s, color .12s; }
  .nav:hover { background: rgba(255, 255, 255, .06); color: var(--seite-hell); } .nav.aktiv { background: var(--seite-aktiv); color: var(--seite-hell); }
  .nav:focus-visible { outline: 2px solid #7f9cff; outline-offset: 1px; } .nav-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .nav-zahl { font-size: 12px; color: #8a92a0; font-variant-numeric: tabular-nums; } .nav.aktiv .nav-zahl { color: var(--seite-hell); }
  .seitenfuss { margin-top: auto; padding: 12px 10px 4px; border-top: 1px solid rgba(255, 255, 255, .08); font-size: 12px; line-height: 1.45; color: #8a92a0; display: flex; gap: 8px; }
  .seitenfuss .ico { color: #5fd0a0; margin-top: 2px; }
  .haupt-bereich { min-width: 0; }
  .kopf { position: sticky; top: 0; z-index: 5; background: rgba(245, 245, 242, .88); backdrop-filter: blur(10px); border-bottom: 1px solid var(--linie); }
  .kopf-innen { max-width: 980px; margin: 0 auto; padding: 14px 28px; display: flex; align-items: center; gap: 14px; }
  .kopf h1 { margin: 0; font-size: 19px; font-weight: 650; letter-spacing: -.02em; } .kopf .datum { color: var(--tinte-3); font-size: 12.5px; }
  .suche { position: relative; margin-left: auto; width: min(340px, 40vw); } .suche .ico { position: absolute; left: 11px; top: 10px; color: var(--tinte-3); }
  .suche input { width: 100%; height: 36px; padding: 0 38px 0 34px; border: 1px solid var(--linie-stark); border-radius: 10px; font: inherit; background: var(--flaeche); color: var(--tinte); box-shadow: var(--schatten-1); }
  .suche input::placeholder { color: var(--tinte-3); } .suche kbd { position: absolute; right: 9px; top: 8px; font: 500 11px var(--schrift); color: var(--tinte-3); border: 1px solid var(--linie-stark); border-radius: 5px; padding: 1px 6px; background: var(--leinwand); }
  .suche input:focus { outline: 2px solid var(--akzent); outline-offset: 1px; border-color: transparent; }
  .neu { height: 36px; width: 36px; display: grid; place-items: center; border: 1px solid var(--linie-stark); border-radius: 10px; background: var(--flaeche); color: var(--tinte-2); text-decoration: none; box-shadow: var(--schatten-1); } .neu:hover { background: var(--leinwand); }
  main { max-width: 980px; margin: 0 auto; padding: 22px 28px 64px; }
  .streifen { display: grid; grid-template-columns: repeat(3, 1fr); background: var(--flaeche); border: 1px solid var(--linie); border-radius: 14px; box-shadow: var(--schatten-1); margin-bottom: 8px; }
  .zahlfeld { padding: 14px 20px; display: flex; flex-direction: column; gap: 2px; } .zahlfeld + .zahlfeld { border-left: 1px solid var(--linie); }
  .zahlfeld b { font-size: 26px; font-weight: 650; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; } .zahlfeld span { color: var(--tinte-3); font-size: 12.5px; }
  .zahlfeld.gelb b { color: var(--warn); } .zahlfeld.gruen b { color: var(--ok); }
  h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--tinte-3); font-weight: 600; margin: 26px 2px 10px; display: flex; align-items: center; gap: 8px; }
  h2 .zahl { background: var(--flaeche); border: 1px solid var(--linie); border-radius: 999px; padding: 0 8px; font-size: 11.5px; letter-spacing: 0; text-transform: none; font-variant-numeric: tabular-nums; color: var(--tinte-2); }
  .liste { background: var(--flaeche); border: 1px solid var(--linie); border-radius: 14px; box-shadow: var(--schatten-1); overflow: hidden; }
  details.zeile { border-bottom: 1px solid var(--linie); position: relative; } details.zeile:last-child { border-bottom: 0; }
  details.zeile > summary { list-style: none; cursor: pointer; display: grid; grid-template-columns: 8px 132px minmax(0, 1fr) auto auto 14px; column-gap: 12px; row-gap: 6px; align-items: center; padding: 12px 16px; transition: background .12s; }
  details.zeile > summary::-webkit-details-marker { display: none; } details.zeile > summary:hover { background: #fafaf8; }
